target.css:
:root {
  --cream: #f7f0e3;
  --brown-dark: #3b2a1a;
  --brown-mid: #7a5230;
  --brown-light: #c49a6c;
  --red-accent: #b83232;
  --green-accent: #2e7d52;
  --ink-black: #1a1a1a;
  --rule-color: #d4b896;
  --highlight-row: #fdf3e7;
  --tech-bg: #e8d9c4;
  --footer-bg: #3b2a1a;
  --footer-text: #f7f0e3;
}

article.receipt {
  background-color: var(--cream);
  border: 2px solid var(--brown-light);
  border-radius: 6px;
  width: 476px;
  overflow: hidden;
  font-size: 12px;
  color: var(--ink-black);
}

.receipt-header {
  display: flex;
  align-items: center;
  gap: 8px;
  background-color: var(--brown-dark);
  padding: 8px 12px;
  border-bottom: 3px solid var(--brown-light);
}

.shop-logo {
  font-size: 24px;
  line-height: 1;
  flex-shrink: 0;
}

.shop-info {
  flex: 1;
}

.shop-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--footer-text);
  margin: 0 0 1px 0;
  letter-spacing: 0.03em;
  line-height: 1.2;
}

.shop-tagline {
  font-size: 9px;
  color: var(--brown-light);
  margin: 0;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.receipt-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  flex-shrink: 0;
}

.receipt-num {
  font-size: 11px;
  font-weight: 700;
  color: var(--brown-light);
  letter-spacing: 0.05em;
}

.receipt-date {
  font-size: 10px;
  color: var(--footer-text);
  opacity: 0.7;
}

.machine-info {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-bottom: 1px solid var(--rule-color);
  background-color: var(--cream);
}

.machine-tag {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 5px 10px;
  border-right: 1px solid var(--rule-color);
}

.machine-tag:last-child {
  border-right: none;
}

.machine-label {
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--brown-mid);
  font-weight: 600;
}

.machine-value {
  font-size: 11px;
  font-weight: 700;
  color: var(--brown-dark);
}

.condition-bad {
  color: var(--red-accent);
}

.condition-good {
  color: var(--green-accent);
}

.services {
  padding: 0 12px 6px;
}

.services-header {
  display: grid;
  grid-template-columns: 1fr 36px 58px;
  gap: 4px;
  padding: 5px 6px;
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--brown-mid);
  border-bottom: 2px solid var(--brown-light);
  margin-top: 4px;
}

.services-header span:last-child {
  text-align: right;
}

.service-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.service-item {
  display: grid;
  grid-template-columns: 1fr 36px 58px;
  gap: 4px;
  padding: 5px 6px;
  border-bottom: 1px dashed var(--rule-color);
  align-items: center;
  border-radius: 3px;
}

.service-item.highlight {
  background-color: var(--highlight-row);
  border-bottom-style: solid;
  border-bottom-color: var(--brown-light);
}

.service-name {
  font-size: 11px;
  color: var(--ink-black);
  line-height: 1.2;
}

.service-tech {
  font-size: 9px;
  font-weight: 700;
  color: var(--brown-mid);
  background-color: var(--tech-bg);
  border-radius: 3px;
  text-align: center;
  padding: 1px 3px;
  justify-self: start;
}

.service-price {
  font-size: 11px;
  font-weight: 600;
  color: var(--brown-dark);
  text-align: right;
}

.receipt-footer {
  display: flex;
  align-items: stretch;
  background-color: var(--footer-bg);
  border-top: 3px solid var(--brown-light);
}

.warranty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 8px 12px;
  border-right: 1px solid var(--brown-mid);
  flex-shrink: 0;
}

.warranty-icon {
  font-size: 18px;
  line-height: 1;
}

.warranty-text {
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--brown-light);
  text-align: center;
  line-height: 1.3;
  max-width: 52px;
}

.totals {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 6px 14px;
  gap: 3px;
}

.total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.total-row.subtotal span,
.total-row.tax span {
  font-size: 10px;
  color: var(--brown-light);
}

.total-row.grand span {
  font-size: 12px;
  font-weight: 700;
  color: var(--footer-text);
}

.total-row.grand span:last-child {
  font-size: 15px;
  color: var(--brown-light);
}

